"use strict";(globalThis.webpackChunkgrc||=[]).push([[54234],{23763(e){e.exports=JSON.parse('{"citeKey":"devarajan2020hfetch","slug":"devarajan-2020-hfetch-46e9","title":"HFetch: Hierarchical Data Prefetching for Scientific Workflows in Multi-Tiered Storage Environments","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"IEEE International Parallel and Distributed Processing Symposium (IPDPS\'20), May 18-22, 2020","type":"Conference","entryType":"inproceedings","date":"May, 2020","year":2020,"era":"iit","month":5,"doi":"10.1109/ipdps47924.2020.00017","abstract":"In the era of data-intensive computing, accessing data with a high-throughput and low-latency is more imperative than ever. Data prefetching is a well-known technique for hiding read latency. However, existing solutions do not consider the new deep memory and storage hierarchy and also suffer from under-utilization of prefetching resources and unnecessary evictions. Additionally, existing approaches implement a client- pull model where understanding the application\'s I/O behavior drives prefetching decisions. Moving towards exascale, where machines run multiple applications concurrently by accessing files in a workflow, a more data-centric approach can resolve challenges such as cache pollution and redundancy. In this study, we present HFetch, a truly hierarchical data prefetcher that adopts a server-push approach to data prefetching. We demonstrate the benefits of such an approach. Results show 10- 35% performance gains over existing prefetchers and over 50% when compared to systems with no prefetching.","hasAbstract":true,"lede":"In this study, we present HFetch, a truly hierarchical data prefetcher that adopts a server-push approach to data prefetching.","links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hfetch-46e9.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hfetch-46e9-slides.pdf"},"tags":["Hierarchical","Multi-Tiered","Data Prefetching","Data-Fetching","Dynamic Choice","Data-Centric","Library","Middleware","Engine","Data-Aware","Workflow-Aware","Server-Push","Hermes"],"_projectIds":["hermes","iris"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["hermes","iris"],"memberAuthors":["devarajan-hariharan","kougkas-anthony","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"CSR-1814872","projectId":"iris"}]}')}}]);